import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"联盟领地","description":"","frontmatter":{},"headers":[],"relativePath":"towns/GuildClaims.md","filePath":"towns/GuildClaims.md"}'),r={name:"towns/GuildClaims.md"};function l(c,t,i,s,n,g){return e(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="联盟领地" tabindex="-1">联盟领地 <a class="header-anchor" href="#联盟领地" aria-label="Permalink to &quot;联盟领地&quot;">​</a></h1><p>联盟领地是<a href="./">联盟</a>的公共领地，大家一起建设生产设施（刷怪塔、农场、市场），权限按联盟职位分享。</p><blockquote><p>由服务器自研插件 <strong>PepperClaim</strong> 提供。个人专属的家园领地见<a href="./PersonalClaims.html">个人领地</a>。</p></blockquote><h2 id="快速认识-gclaim" tabindex="-1">快速认识 /gclaim <a class="header-anchor" href="#快速认识-gclaim" aria-label="Permalink to &quot;快速认识 /gclaim&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim create &lt;名字&gt;</code></td><td>按当前选区创建联盟领地（先金锄框地）</td></tr><tr><td><code>/gclaim list [页数]</code></td><td>本盟领地列表</td></tr><tr><td><code>/gclaim tp [领地]</code></td><td>传送到本盟领地（不填传送到枢纽）</td></tr><tr><td><code>/gclaim map</code></td><td>周边领地地图</td></tr><tr><td><code>/gclaim info [领地]</code></td><td>查看联盟领地详情</td></tr><tr><td><code>/gclaim resize &lt;领地&gt;</code></td><td>扩边/缩地（先 <code>expand</code> / 金锄框好）</td></tr><tr><td><code>/gclaim set welcome &lt;领地&gt; &lt;消息&gt;</code></td><td>联盟领地进出消息（同家园）</td></tr><tr><td><code>/gclaim set preset &lt;领地&gt; 半开放</code></td><td>联盟领地档位</td></tr><tr><td><code>/gclaim settp</code></td><td>设置联盟领地传送点</td></tr><tr><td><code>/gclaim buy &lt;块数&gt;</code></td><td>用公会金库买联盟额度</td></tr><tr><td><code>/gclaim quota</code></td><td>联盟额度与槽位概览</td></tr><tr><td><code>/gclaim gui</code></td><td>联盟领地图形界面</td></tr></tbody></table><h2 id="创建联盟领地" tabindex="-1">创建联盟领地 <a class="header-anchor" href="#创建联盟领地" aria-label="Permalink to &quot;创建联盟领地&quot;">​</a></h2><ol><li>拿金锄<strong>左键</strong>点一个角（pos1），走到对角<strong>右键</strong>点另一个角（pos2）。</li><li>确认粒子轮廓为绿色（合法），输入：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim create 联盟驻地</span></span></code></pre></div><p>圈地规则与个人领地一致：不能重叠、出生点 100 格内禁圈、主城禁圈；另外联盟领地之间需保持 <strong>8 格</strong>间距。</p><h2 id="槽位与子领地" tabindex="-1">槽位与子领地 <a class="header-anchor" href="#槽位与子领地" aria-label="Permalink to &quot;槽位与子领地&quot;">​</a></h2><ul><li>联盟能开几块领地由<strong>槽位</strong>决定：初始 <strong>3 块</strong>，可通过繁荣度提升/购买扩展槽增加（至多 <strong>6 块</strong>）。</li><li>每块联盟领地内可划分<strong>子领地</strong>（功能分区，无属主，全盟共享权限），最多 <strong>10 个</strong>：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim sub create 商店区</span></span></code></pre></div><h2 id="职位权限" tabindex="-1">职位权限 <a class="header-anchor" href="#职位权限" aria-label="Permalink to &quot;职位权限&quot;">​</a></h2><p>联盟领地内能做什么，由联盟职位决定：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim perms &lt;领地&gt;                  # 查看职位权限</span></span>
<span class="line"><span>/gclaim perm &lt;领地&gt; &lt;职位&gt; &lt;旗标&gt; &lt;值&gt; # 给某职位开某旗标（如 build ALLOW）</span></span></code></pre></div><p>常用旗标与取值见<a href="./PersonalClaims.html#旗标-细粒度保护">个人领地</a>，完整职位体系见<a href="./Roles.html">职位与权限</a>。</p><h2 id="繁荣度与领地之心" tabindex="-1">繁荣度与领地之心 <a class="header-anchor" href="#繁荣度与领地之心" aria-label="Permalink to &quot;繁荣度与领地之心&quot;">​</a></h2><ul><li>成员在联盟领地内活动（生产、狩猎、驻留）会涨<strong>联盟活跃度</strong>（不能买），详见<a href="./Advancements.html">繁荣度与活跃度</a>。</li><li><code>/gclaim prosperity</code> 查看繁荣度详情；<code>/gclaim top</code> 查看活跃榜。</li></ul><p><strong>领地之心</strong>：把满级信标注册为联盟灯塔，解锁传送与特效：</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim heart register</code></td><td>把脚下满级信标注册为领地之心</td></tr><tr><td><code>/gclaim heart unregister</code></td><td>注销领地之心</td></tr><tr><td><code>/gclaim heart effect</code></td><td>查看/切换信标特效</td></tr><tr><td><code>/gclaim heart info</code></td><td>查看领地之心信息</td></tr><tr><td><code>/gclaim heart public on/off</code></td><td>开关公开传送（银锭档位以上）</td></tr></tbody></table><h2 id="额度与经济" tabindex="-1">额度与经济 <a class="header-anchor" href="#额度与经济" aria-label="Permalink to &quot;额度与经济&quot;">​</a></h2><p>联盟额度用<strong>联盟金库</strong>购买：</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim quota</code></td><td>查看联盟额度与槽位</td></tr><tr><td><code>/gclaim buy &lt;块数&gt;</code></td><td>用公会金库购买联盟额度</td></tr><tr><td><code>/gclaim worldslot &lt;世界&gt;</code></td><td>购买世界专用扩展槽</td></tr></tbody></table><blockquote><p>联盟金库存取见<a href="./#联盟账户">联盟</a>。</p></blockquote><h2 id="保护机制" tabindex="-1">保护机制 <a class="header-anchor" href="#保护机制" aria-label="Permalink to &quot;保护机制&quot;">​</a></h2><p>联盟领地享受与个人领地相同的保护：</p><ul><li><strong>死亡掉落锁定</strong>：领地内死亡掉落物 60 秒内仅本人可拾取。</li><li><strong>安全传送</strong>：自动计算安全落点，失败拒绝传送；传送有 30 秒冷却。</li><li><strong>防重叠与间距</strong>：圈地自动校验重叠、出生点与联盟间距。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：伙伴进不来联盟领地？</strong> 给伙伴所在职位开 <code>move</code> 旗标：<code>/gclaim perm &lt;领地&gt; 成员 move ALLOW</code>；或把档位调为「半开放/开放」。</p><p><strong>Q：成员能建不能开箱？</strong> 检查 <code>container</code> 旗标：<code>/gclaim perm &lt;领地&gt; 成员 container ALLOW</code>。</p><p><strong>Q：联盟领地能被其他联盟破坏吗？</strong> 不能。联盟领地默认只允许本盟成员按职位权限操作，其他联盟成员视为陌生人（受档位约束）。</p><p><strong>Q：槽位用完了怎么办？</strong> 通过繁荣度提升解锁，或用 <code>/gclaim worldslot &lt;世界&gt;</code> 购买世界扩展槽；单块联盟领地内最多 10 个子领地，可把设施分区建在子领地里。</p><h2 id="市场" tabindex="-1">市场 <a class="header-anchor" href="#市场" aria-label="Permalink to &quot;市场&quot;">​</a></h2><blockquote><p>当前服务器的租赁（<code>rent</code>）与拍卖（<code>auction</code>）功能<strong>未开放</strong>，如提示&quot;该功能已在服务器配置中禁用&quot;即属正常。</p></blockquote>`,34)])])}const m=a(r,[["render",l]]);export{p as __pageData,m as default};
